import fs from 'node:fs';
import path from 'node:path';
import type { z } from 'zod';
import {
  BlockersSchema,
  IndexSchema,
  ModuleSchema,
  PrerequisitesSchema,
  TestDataSchema,
  type Blockers,
  type Journey,
  type Module,
  type Prerequisites,
  type TestCase,
  type TestData,
} from './schema';

/**
 * Typed, validated access to the workbook data in test-data/reference/
 * (generated by `npm run qa:data`). Every read is checked with zod and fails
 * loudly when the JSON no longer matches the expected columns.
 */

const ROOT = path.resolve(__dirname, '..', '..');
const DATA_DIR = path.join(ROOT, 'test-data', 'reference');

function load<S extends z.ZodTypeAny>(rel: string, schema: S): z.infer<S> {
  const file = path.join(DATA_DIR, rel);
  if (!fs.existsSync(file)) throw new Error(`${file} is missing: run "npm run qa:data"`);
  const parsed = schema.safeParse(JSON.parse(fs.readFileSync(file, 'utf8')));
  if (!parsed.success) {
    const issues = parsed.error.issues.slice(0, 5).map((i) => `${i.path.join('.')}: ${i.message}`);
    throw new Error(`${rel} does not match its schema:\n  ${issues.join('\n  ')}`);
  }
  return parsed.data;
}

let cache: {
  prerequisites: Prerequisites;
  testData: TestData;
  blockers: Blockers;
  modules: Map<string, Module>;
} | null = null;

function data() {
  if (!cache) {
    const index = load('index.json', IndexSchema);
    const modules = new Map<string, Module>();
    for (const slug of index.modules) modules.set(slug, load(`modules/${slug}.json`, ModuleSchema));
    cache = {
      prerequisites: load('prerequisites.json', PrerequisitesSchema),
      testData: load('test-data.json', TestDataSchema),
      blockers: load('blockers.json', BlockersSchema),
      modules,
    };
  }
  return cache;
}

export const prerequisites = (): Prerequisites => data().prerequisites;
export const testData = (): TestData => data().testData;
export const blockers = (): Blockers => data().blockers;
export const modules = (): Module[] => [...data().modules.values()];

/** A module by its file slug ("01-ambulatory-care") or its number ("01"). */
export function moduleOf(key: string): Module {
  const m = data().modules.get(key) ?? modules().find((x) => x.slug.startsWith(`${key}-`));
  if (!m) throw new Error(`No workbook for module "${key}"`);
  return m;
}

export interface TestCaseRef {
  module: Module;
  testCase: TestCase;
  journey: Journey;
  /** 00-prerequisites.xlsx | Journeys row of this journey. */
  needs: Prerequisites['journeys'][number];
}

/** Looks up a test case (e.g. "TC-APP001-001") with its journey and its prerequisites. */
export function testCaseRef(id: string): TestCaseRef {
  const num = id.match(/^TC-APP(\d{3})-/)?.[1];
  if (!num) throw new Error(`Not a test case id: ${id}`);
  const module = moduleOf(num.slice(1));
  const testCase = module.testCases.find((t) => t.id === id);
  if (!testCase) throw new Error(`${id} is not in ${module.source}`);
  const journey = module.journeys.find((j) => j.id === testCase.journeyId);
  if (!journey) throw new Error(`${testCase.journeyId} of ${id} is not in ${module.source}`);
  const needs = prerequisites().journeys.find((j) => j.journeyId === journey.id);
  if (!needs) throw new Error(`${journey.id} is not in 00-prerequisites.xlsx | Journeys`);
  return { module, testCase, journey, needs };
}

/** Login of a prepared user, read from "Status on the site" ("Exists: rs.admin2"). */
export function userLogin(key: string): string | null {
  const u = prerequisites().users.find((x) => x.key === key);
  if (!u) throw new Error(`User ${key} is not in 00-prerequisites.xlsx | Users`);
  return u.statusOnSite.match(/^Exists:\s*(\S+)/)?.[1] ?? null;
}

/** Catalogue records of a module ("00-test-data.xlsx | Data catalogue"). */
export function catalogueOf(moduleNumber: string) {
  return testData().catalogue.filter((c) => c.application.startsWith(`${moduleNumber} `));
}

/** Journeys of a blocker ("00-blockers-checklist-linked.xlsx | Journey links"). */
export function blockersOfJourney(journeyId: string) {
  const nos = new Set(blockers().links.filter((l) => l.journeyId === journeyId).map((l) => l.blockerNo));
  return blockers().blockers.filter((b) => nos.has(b.no));
}
